// Key-frame check: seek to given seconds, screenshot, and tile a contact sheet (ffmpeg).
//   node tools/snap.mjs <project-dir> <out-dir> <t1> <t2> ...   -> out-dir/sheet.jpg (+ per-frame PNGs)
// Also prints the page's cue lists (OPENER.SFX / OPENER.MUSIC) to out-dir/cues.json for the sound step.
import { createRequire } from 'node:module';
const { chromium } = createRequire(import.meta.url)(process.env.BM_PLAYWRIGHT || 'playwright');  // global install (VPS: npm i -g playwright)
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { pageUrl } from './serve.mjs';
import path from 'node:path';

const [dir, outDir, ...times] = process.argv.slice(2);
if (!dir || !outDir) { console.error('usage: node tools/snap.mjs <project-dir> <out-dir> <t...>'); process.exit(2); }
mkdirSync(outDir, { recursive: true });
const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
const srv = await pageUrl(dir); await page.goto(srv.url);
await page.waitForFunction('window.OPENER && window.OPENER.ready', null, { timeout: 120000 });
const { W, H, D } = await page.evaluate(() => ({ W: OPENER.W, H: OPENER.H, D: OPENER.DURATION }));
await page.setViewportSize({ width: W, height: H });
writeFileSync(path.join(outDir, 'cues.json'), JSON.stringify(await page.evaluate(() => ({ duration: OPENER.DURATION, sfx: OPENER.SFX || [], music: OPENER.MUSIC || [] })), null, 1));
const files = [];
for (const ts of times) {
  const t = Math.min(Number(ts), D - 0.001);
  await page.evaluate(async t => { await (OPENER.seekFrame || OPENER.seek)(t); await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))); }, t);
  const f = path.join(outDir, `t${t.toFixed(2).padStart(6, '0')}.png`);
  await page.screenshot({ path: f }); files.push(f);
}
await browser.close(); srv.close();
const cols = Math.min(files.length, W < H ? 6 : 4), tw = W < H ? 270 : 480;
const inputs = files.flatMap(f => ['-i', f]);
const fc = files.map((_, i) => `[${i}:v]scale=${tw}:-1,drawtext=text='${Number(times[i]).toFixed(2)}s':x=8:y=8:fontsize=22:fontcolor=yellow:box=1:boxcolor=black@0.6[v${i}]`).join(';')
  + ';' + files.map((_, i) => `[v${i}]`).join('') + `xstack=inputs=${files.length}:layout=${files.map((_, i) => `${(i % cols) ? Array.from({ length: i % cols }, () => 'w0').join('+') : 0}_${Math.floor(i / cols) ? Array.from({ length: Math.floor(i / cols) }, () => 'h0').join('+') : 0}`).join('|')}:fill=black`;
if (files.length > 1) execFileSync('ffmpeg', ['-v', 'error', '-y', ...inputs, '-filter_complex', fc, '-frames:v', '1', path.join(outDir, 'sheet.jpg')]);
console.log(path.join(outDir, 'sheet.jpg') + (errors.length ? `\nPAGE ERRORS: ${errors.join(' | ')}` : ''));
['scratch', 'crash', 'gasp', 'spit', 'alarm', 'trombone', 'paper', 'rain', 'creak', 'flutter', 'ding', 'riser', 'whoosh', 'register', 'coin', 'pop', 'horn', 'fall', 'impact', 'shatter', 'thud', 'slurp', 'slurp_empty', 'buzz', 'boing', 'twitch', 'cash_tiny', 'sting', 'crack', 'hit', 'sub_drop', 'shimmer', 'tick', 'swell', 'glint', 'swoosh', 'punch', 'bonk', 'glitch', 'keys', 'step', 'tiptoe', 'door', 'notify', 'rimshot', 'cricket', 'drumroll', 'zip', 'gulp', 'heartbeat', 'shutter', 'squeak', 'laugh', 'boom', 'zoom_in', 'clap', 'slide_down', 'slide_up', 'wrong', 'dun', 'eyepop', 'squish', 'gong']
VDIR = os.environ.get('BM_VOICES', os.path.join(HERE, 'voices', 'vits-piper-en_US-libritts_r-medium'))
# fixed casting (speaker id, speed): chosen by measured pitch; male ~86-92 Hz, female ~200-245 Hz
CAST = {'dave': (552, 1.05), 'omar': (132, .95), 'kenji': (426, 1.0), 'sam': (36, 1.05), 'rex': (186, .92),
        'maya': (624, 1.03), 'lina': (372, 1.0), 'grace': (450, .93), 'zara': (378, 1.06), 'leo': (60, 1.1), 'narrator': (186, 1.0),
        # Sarcastic Grotesque cast (lib/grotesque.js)
        'gary': (426, .9), 'brock': (186, .94), 'kyle': (552, 1.14), 'vlad': (36, 1.12), 'tiff': (378, 1.1), 'bev': (450, .95),
        'zeke': (342, 1.08), 'marco': (594, 1.02), 'dale': (738, 1.1), 'pip': (60, 1.15)}
SR_OUT = 48000

def engine():
    import sherpa_onnx
    m = [f for f in os.listdir(VDIR) if f.endswith('.onnx')][0]
    cfg = sherpa_onnx.OfflineTtsConfig(model=sherpa_onnx.OfflineTtsModelConfig(vits=sherpa_onnx.OfflineTtsVitsModelConfig(
        model=os.path.join(VDIR, m), tokens=os.path.join(VDIR, 'tokens.txt'), data_dir=os.path.join(VDIR, 'espeak-ng-data')), num_threads=2))
    return sherpa_onnx.OfflineTts(cfg)

def trim(x, sr, th=.01):
    idx = np.where(np.abs(x) > th)[0]
    return x[max(0, idx[0] - int(.02 * sr)): idx[-1] + int(.05 * sr)] if len(idx) else x

def main():
    a = sys.argv[1:]
    if len(a) < 2: print(__doc__); sys.exit(2)
    spec = json.load(open(a[0])); out = a[1]; os.makedirs(out, exist_ok=True)
    tts = engine(); clips = []; t = spec.get('start', .3)
    for i, ln in enumerate(spec['lines']):
        sid, spd = CAST.get(ln['who'], CAST['narrator'])
        g = tts.generate(ln['text'], sid=ln.get('sid', sid), speed=ln.get('speed', spd))
        x = trim(np.array(g.samples, dtype=np.float32), g.sample_rate)
        x = np.interp(np.arange(int(len(x) * SR_OUT / g.sample_rate)) * g.sample_rate / SR_OUT, np.arange(len(x)), x)   # resample to 48 kHz
        t0 = ln['t0'] if 't0' in ln else t; d = len(x) / SR_OUT
        clips.append((t0, x, {'who': ln['who'], 'text': ln['text'], 't0': round(t0, 3), 't1': round(t0 + d, 3)}))
        t = t0 + d + ln.get('gap', spec.get('gap', .25))
    D = max(spec.get('duration', 0), t + .5); buf = np.zeros(int(D * SR_OUT), np.float32)
    for t0, x, _ in clips:
        s = int(t0 * SR_OUT); buf[s:s + len(x)] += x[: len(buf) - s]
    buf = buf / (np.max(np.abs(buf)) + 1e-9) * .89
    wav = os.path.join(out, 'dialog.wav')
    subprocess.run(['ffmpeg', '-y', '-v', 'error', '-f', 'f32le', '-ar', str(SR_OUT), '-ac', '1', '-i', '-', wav], input=buf.tobytes(), check=True)
    lines = []
    for _, _, m in clips: m['visemes'] = visemes(wav, 30, m['t0'], m['t1']); lines.append(m)
    res = {'duration': round(D, 3), 'lines': lines}
    json.dump(res, open(os.path.join(out, 'dialog.json'), 'w'))
    open(os.path.join(out, 'dialog.js'), 'w').write('window.DIALOG = ' + json.dumps(res) + ';\n')
    for m in lines: print(f"{m['t0']:6.2f}-{m['t1']:6.2f}  {m['who']:6s} {m['text']}")
    print('voice ->', wav, f'({len(lines)} lines, {D:.1f}s)')

